import sqlite3
conn = sqlite3.connect('/root/data/eventlogs.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

print("=== DC01 Logon Events (4624) ===")
cur.execute("SELECT event_id, timestamp, message FROM events WHERE host='DC01.corp.example' AND event_code=4624")
for r in cur.fetchall():
    print(r['event_id'], r['timestamp'])
    for line in r['message'].split('\n'):
        if any(k in line for k in ('Logon Type:', 'Source Network Address:', 'Account Name:', 'Workstation Name:')):
            print("  ", line.strip())

print("\n=== DC01 Share Access (5140/5145) ===")
cur.execute("SELECT event_id, timestamp, event_code, message FROM events WHERE host='DC01.corp.example' AND event_code IN (5140, 5145)")
for r in cur.fetchall():
    print(r['event_id'], r['timestamp'], r['event_code'])
    for line in r['message'].split('\n'):
        if any(k in line for k in ('Share Name:', 'Source Address:', 'Account Name:', 'Relative Target Name:')):
            print("  ", line.strip())

print("\n=== File Creations (Event 11) on all hosts ===")
cur.execute("SELECT event_id, timestamp, host, message FROM events WHERE event_code=11")
for r in cur.fetchall():
    print(r['event_id'], r['timestamp'], r['host'])
    for line in r['message'].split('\n'):
        if any(k in line for k in ('TargetFilename:', 'Image:', 'User:')):
            print("  ", line.strip())

